//! The web designer's prompts (ADR-0093, FEAT-115): the `web design template` call (one
//! template or part) and its `web design template fix` repair turns.
//!
//! Both are one structured call answering `{"content": "<block markup>"}`
//! ([`answer_schema`]); the orchestrator checks the markup
//! (`theme_designer::check_template`) and drives the repair loop
//! (`theme_designer::next_step`). This module only renders what the model reads: the
//! design's context (generated by `theme_designer::plan::prompt_context`), the task and the
//! presets as JSON after the marks the fake designer reads
//! (`theme_designer::fake::{TASK_MARK, PRESETS_MARK}`).

use serde_json::{json, Value};
use theme_designer::fake::{PRESETS_MARK, TASK_MARK};
use theme_designer::{Presets, TemplateTask};

/// Answer budget of a template or a part, tokens (a front page with seven sections in the
/// component vocabulary is about 5,000).
pub const TEMPLATE_ANSWER: u32 = 12_288;
/// Reasoning budget of a template or a fix, tokens: a page laid out from a design system
/// is the office designer's kind of puzzle (`crate::build::LAYOUT_REASONING`), with more
/// to keep in mind.
pub const TEMPLATE_REASONING: u32 = 4096;

/// `{"content": "<block markup>"}`.
pub fn answer_schema() -> Value {
    json!({
        "type": "object",
        "properties": {"content": {"type": "string", "minLength": 1}},
        "required": ["content"],
        "additionalProperties": false
    })
}

/// What a template call works from.
#[derive(Debug, Clone, Copy)]
pub struct TemplateInput<'a> {
    pub task: &'a TemplateTask,
    pub presets: &'a Presets,
    /// `theme_designer::plan::prompt_context`: the design, the presets in words, the site's pages.
    pub context: &'a str,
}

/// The theme's component classes in words (`theme_designer::components::VOCABULARY`).
pub fn vocabulary() -> String {
    theme_designer::components::VOCABULARY
        .iter()
        .map(|(c, what)| format!("- `{c}`: {what}"))
        .collect::<Vec<_>>()
        .join("\n")
}

fn body(input: &TemplateInput<'_>) -> String {
    format!(
        "{}\n\nThe theme's component classes (its styles give them the design's look; use them by className):\n{}\n\n{TASK_MARK}\n```json\n{}\n```\n\n{PRESETS_MARK}\n```json\n{}\n```\n\nA draft that passes the checks, in the component classes (start from it; keep its section classes, queries, bindings and menus; make it match the design's markup where it does not):\n```html\n{}\n```",
        input.context.trim(),
        vocabulary(),
        serde_json::to_string_pretty(input.task).unwrap_or_default(),
        serde_json::to_string(input.presets).unwrap_or_default(),
        theme_designer::sketch::template(input.task, input.presets).trim()
    )
}

/// The `web design template fix` call after the visual comparison: the task, the markup as it
/// is, and the regions that look least like the design, each with its score, the design's
/// markup and the rendered markup of the region.
pub fn visual_fix_prompt(input: &TemplateInput<'_>, markup: &str, regions: &str) -> String {
    format!(
        "## Task: web design template fix\n\nThe {} \"{}\" was rendered on the site and compared with the design, region by region (pictures masked; 1000 is the same picture). Rework the regions below so they look like the design: their layout (columns, rows, order), type sizes, rules, grounds and spacing, with the component classes. Keep every section, query, binding, menu and part, and keep what already matches.\n\n{}\n\nYour markup:\n```html\n{}\n```\n\nThe regions furthest from the design:\n{}\n\nAnswer {{\"content\": \"<block markup>\"}}: the whole template again.",
        input.task.label(),
        input.task.title,
        body(input),
        markup.trim(),
        regions.trim()
    )
}

/// The `web design template` call's user message.
pub fn template_prompt(input: &TemplateInput<'_>) -> String {
    format!(
        "## Task: web design template\n\nWrite the {} \"{}\" as block markup.\n\n{}\n\nAnswer {{\"content\": \"<block markup>\"}}.",
        input.task.label(),
        input.task.title,
        body(input)
    )
}

/// The `web design template fix` call's user message: the task again (the call stands
/// alone), the markup as it is, and the repair task's text
/// (`theme_designer::RepairTask::prompt`).
pub fn fix_prompt(input: &TemplateInput<'_>, markup: &str, issues: &str) -> String {
    format!(
        "## Task: web design template fix\n\nFix the {} \"{}\".\n\n{}\n\nYour markup:\n```html\n{}\n```\n\n{}",
        input.task.label(),
        input.task.title,
        body(input),
        markup.trim(),
        issues.trim()
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use theme_designer::TaskKind;

    #[test]
    fn prompts_carry_the_task_for_the_fake_and_the_model() {
        let task = TemplateTask {
            kind: TaskKind::Template,
            slug: "404".into(),
            title: "Page not found".into(),
            area: None,
            design: None,
            template_kind: None,
            purpose: Some("Say so.".into()),
            sections: vec![],
            parts: vec!["header".into()],
            menus: vec![],
            html: None,
            components: vec![],
            classes: vec![],
            brand: None,
            search: None,
            forbid: vec![],
        };
        let presets = Presets::default();
        let input = TemplateInput {
            task: &task,
            presets: &presets,
            context: "The design: Salt & Pigment.",
        };
        let p = template_prompt(&input);
        assert!(p.starts_with("## Task: web design template\n"));
        let (t, _) = theme_designer::fake::read(&p).unwrap();
        assert_eq!(t, task);
        let f = fix_prompt(&input, "<!-- wp:group /-->", "- [token] …");
        assert!(f.starts_with("## Task: web design template fix\n"));
        assert!(f.contains("Your markup:\n```html\n<!-- wp:group /-->"));
        assert_eq!(theme_designer::fake::read(&f).unwrap().0, task);
    }
}
